#!/usr/bin/env python3
import sys
import itertools


def solve(N: int, K: int, S: int):
    L = [len(list(v))for k,v in itertools.groupby(S)]
    LL = list(itertools.accumulate(L))
    isFirstZero = (S[0] == "0")
    NN = 2 * K + 1

    res = 0
    start_index = 0
    if isFirstZero:
        start_index = 1
        res = LL[min(2*K-1,len(LL)-1)]

    for i in range(start_index,len(LL),2):
        s = LL[min(i+NN-1,len(LL)-1)]
        if i > 0:
            s -= LL[i-1]
        res = max(res,s)

    print(res)


# Generated by 1.1.4 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))  # type: int
    K = int(next(tokens))  # type: int
    S = next(tokens)  # type: int
    solve(N, K, S)

if __name__ == '__main__':
    main()
